@vincenthage you asked for a test: here is a program which works on a real machine but fails under proot (`heap incorrectly restored`). I am not a C expert, so it might be something no real world program wants to do, but, well...
```c
#define _GNU_SOURCE 
#include <sys/wait.h>
#include <sched.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>

#define STACK_SIZE (1024 * 1024)    /* Stack size for cloned child */
#define CHUNK 1024

static int childFunc(__attribute__((unused)) void* targetvalue) {
   /*
    * the bug is: on execve, the child's tracee->heap will be zeroed.
    * Since this heap is common with the parent, the parent heap metadata
    * is wiped and on next brk a new heap is allocated.
    */
   execlp("echo", "echo", "temoin", (char*)NULL);
   return 0;
}


int main() {
   char *stack;                    /* Start of stack buffer */
   char *stackTop;                 /* End of stack buffer */
   pid_t pid;


   /* Allocate stack for child */
   stack = malloc(STACK_SIZE);
   if (stack == NULL) {
      perror("malloc");
      exit(EXIT_FAILURE);
   }
   stackTop = stack + STACK_SIZE;  /* Assume stack grows downward */

   void* heap_before = sbrk(CHUNK);
   printf("sbrk()=%016x\n", (long)(heap_before));

   pid = clone(childFunc, stackTop, CLONE_VM | SIGCHLD, NULL);
   if (pid == -1) {
      perror("clone");
      exit(EXIT_FAILURE);
   }

   if (waitpid(pid, NULL, 0) == -1) {
      perror("waitpid");
      exit(EXIT_FAILURE);
   }

   /* we try to set the end of the heap before the start of the newly
    * allocated heap. This is ignored by replacing the syscall with void.
    */
   if (brk(heap_before) == -1) {
      perror("brk");
      exit(EXIT_FAILURE);
   }

   if (sbrk(0) != heap_before) {
      fprintf(stderr, "heap incorrectly restored\n");
      exit(EXIT_FAILURE);
   }

   exit(EXIT_SUCCESS);
}
```

